// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-05-explanation-example-mincha-sfarad-ashrei.spec.ts, план .qa/e2e/specs/guided-prayer.md, кейс .qa/tests/guided-prayer/GP-05-section-info-every-fragment.md
// Тикет #6a86f7df · 6a86f7df6f29cb4c367083d2 «עיצוב מוקאפ: תפילה מודרכת — קטע בתוך סדר התפילה». Опора: мокап S-17 (пример пояснения, проверено 04.10).
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabelStartsWith, tapText, expectVisibleText, pageCounter, scrollToText } from '../../helpers/ui.ts';
import { openPrayer, openRoute, hasDeepLinks, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

async function switchNusach(to: 'ספרדי' | 'אשכנזי') {
  await (await byLabelStartsWith('בחירת נוסח')).click();
  await tapText(to);
  const replace = await byText('החלף');
  if (await replace.isDisplayed().catch(() => false)) await replace.click();
  await expectVisibleText(`מנחה (${to})`);
}

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  it('GP-05 Пример пояснения: מנחה ספרד «אשרי» — «תהילה לפני תפילת המנחה» #6a86f7df @prod-safe', async () => {
    // 1. מנחה (ספרדי): deep link или «תפילות» → «מנחה» → меню нусаха → «ספרדי».
    if (hasDeepLinks()) await openRoute('/prayer/mincha_sfarad');
    else { await openPrayer('mincha_ashkenaz', 'מנחה'); await switchNusach('ספרדי'); }
    await (await byTextMatches('\\d+ מתוך \\d+')).waitForDisplayed();

    // 2. «1 מתוך 11» → «המשך» → «2 מתוך 11»: «אשרי», пояснение «תהילה לפני תפילת המנחה», строка «הטקסט עדיין לא אושר…».
    await goToPage(1, 11);
    await tapText('המשך');
    await goToPage(2, 11);
    expect(await pageCounter()).toBe('2 מתוך 11');
    await expectVisibleText('אשרי');
    await scrollToText('תהילה לפני תפילת המנחה');
    await expect(byTextContains('תהילה לפני תפילת המנחה')).toBeDisplayed();
    await scrollToText('הטקסט עדיין לא אושר');
    await expect(byTextMatches('הטקסט עדיין לא אושר.*')).toBeDisplayed();

    // Вернуть מנחה в נוסח профиля.
    if (!hasDeepLinks()) await switchNusach('אשכנזי');
  });
});
